// src/test/planEnforcement/render.ts
//
// Deterministic markdown for docs/plan-enforcement-matrix.md. No timestamps, stable ordering: the file is
// regenerated by `UPDATE_PLAN_MATRIX=1 npx vitest run src/lib/planEnforcementMatrix.test.ts` and drift-checked in CI.

import { EXEMPT_SENDERS, KNOWN_GAPS, SENDER_REGISTRY, type GapId } from './registry';
import { functionFileReferencesGuard } from './scan';
import { LIMITS, MATRIX_PLANS, type Cell, type CrossRow, type MatrixContext } from './matrix';

const esc = (s: string) => s.replace(/\|/g, '\\|').replace(/\n/g, ' ');

function mark(c: Pick<Cell, 'status' | 'gap'>): string {
  switch (c.status) {
    case 'yes': return 'yes';
    case 'n/a': return 'n/a';
    case 'conflict': return `no (conflict, ${c.gap ?? 'see notes'})`;
    default: return c.gap ? `no (${c.gap})` : 'no';
  }
}

export function renderMatrixMarkdown(cells: Cell[], cross: CrossRow[], cx: MatrixContext): string {
  const total = cells.length;
  const count = (s: Cell['status']) => cells.filter((c) => c.status === s).length;
  const usedGaps = new Set<GapId>([...cells.map((c) => c.gap), ...cross.map((c) => c.gap)].filter((g): g is GapId => g !== null));
  const lines: string[] = [];
  lines.push('# Plan enforcement matrix', '');
  lines.push('> GENERATED FILE. Do not edit by hand.', '> Regenerate: `UPDATE_PLAN_MATRIX=1 npx vitest run src/lib/planEnforcementMatrix.test.ts` (PowerShell: `$env:UPDATE_PLAN_MATRIX=1; npx vitest run src/lib/planEnforcementMatrix.test.ts`).', '> CI fails when this file differs from what the tests compute.', '');
  lines.push('A cell says **yes** only when the enforcement logic behaves correctly at its boundary (executed against the real functions) **and** production code actually reaches it. Correct-but-unwired logic is **no** with its gap id. `n/a` means the plan has no such limit or the limit does not apply by design.', '');
  lines.push(`Summary: ${count('yes')} yes, ${count('no') + count('conflict')} no (of which ${count('conflict')} conflicts between sources of truth), ${count('n/a')} n/a, ${total} cells.`, '');
  lines.push('Sources of truth: `src/lib/pricing.ts`, `_shared/billing/planCatalog.ts`, `_shared/fraud/planLimits.ts`, `_shared/entitlements/*`, `src/lib/whiteLabel.ts`. Evidence: executed = real function run in Vitest; static = source/SQL text assertion.', '');
  lines.push('## Plan x limit', '');
  lines.push(`| Limit | ${MATRIX_PLANS.join(' | ')} |`, `| --- | ${MATRIX_PLANS.map(() => '---').join(' | ')} |`);
  for (const l of LIMITS) {
    const row = MATRIX_PLANS.map((p) => {
      const c = cells.find((x) => x.plan === p && x.limit === l.id);
      return c ? mark(c) : '-';
    });
    lines.push(`| ${esc(l.label)} | ${row.join(' | ')} |`);
  }
  lines.push('', '## Expected values and evidence', '');
  lines.push('| Limit | Plan | Expected | Observed | Evidence | Note |', '| --- | --- | --- | --- | --- | --- |');
  for (const c of cells) {
    const label = LIMITS.find((l) => l.id === c.limit)?.label ?? c.limit;
    lines.push(`| ${esc(label)} | ${c.plan} | ${esc(c.expected)} | ${esc(c.actual)} | ${c.evidence} | ${esc(c.note)} |`);
  }
  lines.push('', '## Cross-plan controls', '');
  lines.push('| Control | Enforced | Evidence | Gap | Detail |', '| --- | --- | --- | --- | --- |');
  for (const r of cross) lines.push(`| ${esc(r.control)} | ${mark(r)} | ${r.evidence} | ${r.gap ?? '-'} | ${esc(r.detail)} |`);
  lines.push('', '## Open gaps (ticket ids are placeholders: create them in your tracker)', '');
  lines.push('| Gap | Ticket | Status | Effect | Smallest fix |', '| --- | --- | --- | --- | --- |');
  for (const g of Object.values(KNOWN_GAPS)) {
    const st = cx.gaps.get(g.id);
    const open = st ? st.open : usedGaps.has(g.id);
    lines.push(`| ${g.id} ${esc(g.title)} | ${g.ticket} | ${open ? 'OPEN' : 'closed'} | ${esc(g.effect)} | ${esc(g.fix)} |`);
  }
  lines.push('', '## Sender coverage (customer-driven outbound)', '');
  lines.push('| File (supabase/functions/) | Channel | Calls the guard | Gap |', '| --- | --- | --- | --- |');
  for (const s of SENDER_REGISTRY) lines.push(`| ${s.file} | ${s.channel} | ${functionFileReferencesGuard(s.file) ? 'yes' : 'no'} | ${s.gap ?? '-'} |`);
  lines.push('', '### Exempt (with reason)', '', '| File | Reason |', '| --- | --- |');
  for (const e of EXEMPT_SENDERS) lines.push(`| ${e.file} | ${esc(e.reason)} |`);
  return lines.join('\n') + '\n';
}
